-- Seed 030: Excel-derived sample case_files.
-- Source: database/seed/danh_sach/*.xlsx
-- Generated from workbook rows that have enough data for case_files.
-- Technical note: case_files.court_id is NOT NULL, while these Excel files do not carry a uniform current court column.
-- This seed creates one deterministic source court for the imported Excel sample rows.
-- case_number uses the deterministic Excel case_code to satisfy uq_case_files_court_number_type;
-- the raw Excel case number/date remains in summary.

INSERT INTO courts (court_id, court_code, court_name, court_level, province)
VALUES (uuid_generate_v5(uuid_ns_url(), 'qlta:excel_seed:tand_quang_ngai'), 'EXCEL_SEED_TAND_QNG', 'TAND tinh Quang Ngai - nguon seed Excel', 'province', 'Quang Ngai')
ON CONFLICT (court_code) DO UPDATE SET court_name = EXCLUDED.court_name, court_level = EXCLUDED.court_level, province = EXCLUDED.province, updated_at = CURRENT_TIMESTAMP;

