, court_ref AS (SELECT court_id FROM courts WHERE court_code = 'EXCEL_SEED_TAND_QNG')
, case_stage_ref AS (SELECT item_code, item_id FROM dm_category_items i JOIN dm_categories c ON c.category_id = i.category_id WHERE c.category_code = 'case_stage')
, case_status_ref AS (SELECT item_code, item_id FROM dm_category_items i JOIN dm_categories c ON c.category_id = i.category_id WHERE c.category_code = 'case_status')
, case_group_ref AS (SELECT item_code, item_id FROM dm_category_items i JOIN dm_categories c ON c.category_id = i.category_id WHERE c.category_code = 'case_group')
, procedure_law_ref AS (SELECT item_code, item_id FROM dm_category_items i JOIN dm_categories c ON c.category_id = i.category_id WHERE c.category_code = 'procedure_law')
, case_type_ref AS (SELECT item_code, item_id FROM dm_category_items i JOIN dm_categories c ON c.category_id = i.category_id WHERE c.category_code = 'case_type')
INSERT INTO case_files (case_id, court_id, case_code, case_number, case_type, case_group, procedure_law, filing_date, acceptance_date, current_stage, case_status, resolution_status, summary, case_type_id, case_status_id, case_group_id, procedure_law_id, current_stage_id, resolution_status_id)
SELECT
    uuid_generate_v5(uuid_ns_url(), 'qlta:case_file:' || s.case_code),
    cr.court_id,
    s.case_code,
    s.case_number,
    s.case_type,
    CASE WHEN s.case_type = 'marriage_family' THEN 'marriage_family' WHEN s.case_type = 'business_commercial' THEN 'business_commercial' WHEN s.case_type = 'labor' THEN 'labor' ELSE s.case_type::text END,
    CASE WHEN s.case_type = 'criminal' THEN 'BLTTHS' WHEN s.case_type = 'administrative' THEN 'LTTHC' ELSE 'BLTTDS' END,
    s.filing_date,
    s.acceptance_date,
    s.current_stage,
    s.case_status,
    CASE WHEN s.case_status IN ('resolved','closed','effective') THEN 'resolved' WHEN s.case_status = 'appealed' THEN 'appealed' ELSE NULL END,
    s.summary,
    ctr.item_id,
    csr.item_id,
    cgr.item_id,
    plr.item_id,
    stager.item_id,
    rsr.item_id
FROM source_rows s
CROSS JOIN court_ref cr
LEFT JOIN case_type_ref ctr ON ctr.item_code = s.case_type::text
LEFT JOIN case_status_ref csr ON csr.item_code = s.case_status::text
LEFT JOIN case_group_ref cgr ON cgr.item_code = CASE WHEN s.case_type = 'marriage_family' THEN 'marriage_family' WHEN s.case_type = 'business_commercial' THEN 'business_commercial' WHEN s.case_type = 'labor' THEN 'labor' ELSE s.case_type::text END
LEFT JOIN procedure_law_ref plr ON plr.item_code = CASE WHEN s.case_type = 'criminal' THEN 'BLTTHS' WHEN s.case_type = 'administrative' THEN 'LTTHC' ELSE 'BLTTDS' END
LEFT JOIN case_stage_ref stager ON stager.item_code = s.current_stage
LEFT JOIN case_status_ref rsr ON rsr.item_code = CASE WHEN s.case_status IN ('resolved','closed','effective') THEN 'resolved' WHEN s.case_status = 'appealed' THEN 'appealed' ELSE NULL END
ON CONFLICT (case_code) DO UPDATE SET
    court_id = EXCLUDED.court_id,
    case_number = EXCLUDED.case_number,
    case_type = EXCLUDED.case_type,
    case_group = EXCLUDED.case_group,
    procedure_law = EXCLUDED.procedure_law,
    filing_date = EXCLUDED.filing_date,
    acceptance_date = EXCLUDED.acceptance_date,
    current_stage = EXCLUDED.current_stage,
    case_status = EXCLUDED.case_status,
    resolution_status = EXCLUDED.resolution_status,
    summary = EXCLUDED.summary,
    case_type_id = EXCLUDED.case_type_id,
    case_status_id = EXCLUDED.case_status_id,
    case_group_id = EXCLUDED.case_group_id,
    procedure_law_id = EXCLUDED.procedure_law_id,
    current_stage_id = EXCLUDED.current_stage_id,
    resolution_status_id = EXCLUDED.resolution_status_id,
    updated_at = CURRENT_TIMESTAMP;
